OBSERVABILITY_SECURITY_DAYS = {
86:{"title":"GitHub Actions: Automated Testing & Deployment","phase":"CI/CD & Observability","status":"published","summary":"A CI/CD pipeline should make testing a hard deployment gate so code is promoted only after the checks that protect the release have succeeded.","architecture":"push → build → test → package → deploy","how":["GitHub Actions jobs can depend on other jobs with needs.","A deployment job that declares needs: test is skipped by default when the test job fails.","Keep build artifacts traceable and deployment permissions tightly scoped."],"commands":"test → package → deploy","verify":"Break one test intentionally and confirm deployment is skipped.","gotcha":"Weak tests can produce a green pipeline that confidently ships defects.","security":"Use protected environments and minimum token permissions.","lesson":"Deployment should depend explicitly on successful validation.","evidence":"Published Day 86 journey entry."},
87:{"title":"Prometheus: Turning Running Systems into Measurable Systems","phase":"CI/CD & Observability","status":"published","summary":"Prometheus collects time-series metrics from running systems.","architecture":"application → /metrics → Prometheus → PromQL","how":["Prometheus commonly uses a pull model.","Samples belong to time series identified by metric names and labels.","Select metrics around operational questions."],"commands":"rate(http_requests_total[5m])","verify":"Confirm the target is UP and fresh samples appear.","gotcha":"UP does not prove application health from a user's perspective.","security":"Protect metrics endpoints and avoid secrets in labels.","lesson":"Important system behavior should be measurable.","evidence":"Published Day 87 journey entry."},
88:{"title":"Grafana: Turning Prometheus Metrics into Operational Dashboards","phase":"CI/CD & Observability","status":"published","summary":"Grafana turns metrics into operational dashboards.","architecture":"Prometheus → PromQL → Grafana","how":["Connect Prometheus as a data source.","Build panels around availability, traffic, errors and latency.","Use consistent time ranges and labels."],"commands":"up{job=\"api\"}","verify":"Generate traffic and confirm dashboard panels change.","gotcha":"Graphs are useless if they answer no operational question.","security":"Restrict Grafana and protect data-source credentials.","lesson":"Visualization should shorten investigation time.","evidence":"Published Day 88 journey entry."},
89:{"title":"Centralized Logging: From Scattered Logs to Searchable Evidence","phase":"CI/CD & Observability","status":"published","summary":"Centralized logging gathers distributed logs into a searchable store.","architecture":"applications → collector → central store → query","how":["Collect logs centrally.","Use ELK or Loki-style architectures as appropriate.","Prefer structured contextual fields."],"commands":"Application → Collector → Loki → Grafana","verify":"Generate a known error and locate it centrally.","gotcha":"Centralized noise is still noise.","security":"Redact credentials and control log access and retention.","lesson":"Logs become evidence when structured and correlated.","evidence":"Published Day 89 journey entry."},
90:{"title":"Observability Capstone: Building a Monitoring Dashboard","phase":"CI/CD & Observability","status":"published","summary":"The observability capstone combines metrics and logs into one operational view.","architecture":"application → Prometheus/Loki → Grafana","how":["Use metrics for quantitative signals.","Use logs for detailed evidence.","Correlate both by time and service context."],"commands":"Prometheus + Loki → Grafana","verify":"Trigger an error and correlate the metric change with its log event.","gotcha":"Telemetry that cannot be correlated still leaves investigation gaps.","security":"Apply least privilege to telemetry access.","lesson":"Observability connects symptoms to explanations.","evidence":"Published Day 90 journey entry."},
91:{"title":"AWS Shared Responsibility Model: Who Secures What?","phase":"Cloud Security","status":"published","summary":"AWS secures the cloud infrastructure while customers secure their use of cloud services.","architecture":"AWS: security OF cloud | customer: security IN cloud","how":["AWS handles physical and underlying infrastructure.","Customers handle data, IAM, application and service configuration.","The boundary changes with service abstraction."],"commands":"EC2: guest OS + IAM + VPC + workload config","verify":"Map provider and customer controls for EC2 and a managed service.","gotcha":"A secure cloud provider does not make a customer configuration secure.","security":"Assign explicit ownership to every control.","lesson":"Know which side owns each security responsibility.","evidence":"Published Day 91 journey entry."},
92:{"title":"AWS IAM Best Practices: Least Privilege Is More Than Allow","phase":"Cloud Security","status":"published","summary":"Least privilege grants only required actions, resources and conditions.","architecture":"principal → policies → authorization → resource","how":["Avoid broad wildcards.","Scope actions and resources.","Review effective permissions across policy layers."],"commands":"s3:GetObject + s3:PutObject → arn:aws:s3:::app-data/*","verify":"Confirm required access succeeds and unrelated access fails.","gotcha":"One narrow policy does not prove effective least privilege.","security":"Prefer roles, short-lived credentials and explicit boundaries.","lesson":"Least privilege is an effective-permissions property.","evidence":"Published Day 92 journey entry."},
93:{"title":"AWS Secrets Management: Stop Hardcoding Credentials","phase":"Cloud Security & DevSecOps","status":"published","summary":"Protect application credentials by keeping secrets out of source code and retrieving them through controlled AWS services.","architecture":"Application → IAM Role → Secrets Manager → Secret","how":["Store database credentials, API keys and tokens outside source code.","Retrieve secrets dynamically with narrowly scoped IAM permissions.","Rotate credentials where practical and audit access."],"commands":"secretsmanager:GetSecretValue → production/database","verify":"Confirm the workload can retrieve only its intended secret and cannot read unrelated secrets.","gotcha":"Encrypting a secret is not enough if every workload can retrieve it.","security":"Use KMS, least privilege, rotation and auditing as one lifecycle.","lesson":"The vault is only useful when access to its key is controlled.","evidence":"Manually verified Day 93 LinkedIn publication and artifact."},
94:{"title":"AWS GuardDuty & Security Hub CSPM: From Threat Detection to Security Findings","phase":"Cloud Security & DevSecOps","status":"published","summary":"GuardDuty detects suspicious AWS activity while Security Hub CSPM centralizes and prioritizes security findings.","architecture":"AWS activity → GuardDuty → Finding → Security Hub CSPM → Investigate → Respond","how":["Use GuardDuty for threat detection signals.","Aggregate findings in Security Hub CSPM.","Validate findings with context before deciding on response."],"commands":"GuardDuty finding → Security Hub CSPM","verify":"Confirm GuardDuty findings flow into Security Hub in the intended account and Region.","gotcha":"A finding is a signal, not proof that compromise occurred.","security":"Preventive controls and detection should operate as complementary layers.","lesson":"Detection gives evidence when preventive controls are bypassed or unexpected behavior occurs.","evidence":"Manually verified Day 94 LinkedIn publication and artifact."},
95:{"title":"AWS WAF & Shield: Protecting the Application Edge","phase":"Cloud Security & DevSecOps","status":"published","summary":"AWS WAF filters application-layer web requests while AWS Shield provides DDoS protection for supported AWS resources.","architecture":"Internet → Shield → WAF → Application → Detection/Findings","how":["Inspect HTTP and HTTPS requests with WAF web ACL rules.","Roll managed rules out carefully using observation before enforcement.","Use Shield for the DDoS protection layer."],"commands":"Client → AWS WAF → Web ACL Rules → Application","verify":"Associate the intended web ACL and verify test requests match the expected rules.","gotcha":"Immediately blocking every managed-rule match can break legitimate traffic.","security":"Layer traffic filtering, DDoS protection, detection and centralized findings.","lesson":"Edge protection is strongest when multiple controls solve distinct problems together.","evidence":"Manually verified Day 95 LinkedIn publication and artifact."},
96:{"title":"AWS Security Automation: Turning Findings Into Actions","phase":"Cloud Security & DevSecOps","status":"published","summary":"Security findings can trigger controlled automated response through EventBridge and Lambda.","architecture":"GuardDuty Finding → EventBridge → Lambda → Response","how":["Match security events with EventBridge rules.","Route selected events to a dedicated Lambda response function.","Keep remediation actions specific, logged and least privileged."],"commands":"Finding → EventBridge rule → dedicated Lambda → specific remediation → audit trail","verify":"Trigger a controlled test event and confirm only the intended response path executes.","gotcha":"Automated remediation is itself privileged infrastructure.","security":"Separate low-risk automation from destructive actions that need stronger safeguards.","lesson":"The response mechanism itself needs least privilege, logging, testing and guardrails.","evidence":"Manually verified Day 96 LinkedIn publication and artifact."},
97:{"title":"AWS Security Remediation Workflows: Step Functions & Systems Manager","phase":"Cloud Security & DevSecOps","status":"published","summary":"Multi-step security response can be orchestrated with Step Functions and reusable Systems Manager Automation runbooks.","architecture":"Security Finding → EventBridge → Step Functions → SSM Automation → Remediation → Logs","how":["Receive and classify the finding.","Gather affected-resource context and choose an approved remediation path.","Execute reusable runbooks and retain evidence of success or failure."],"commands":"Finding → EventBridge → Step Functions → SSM Automation → Remediation","verify":"Run a controlled workflow and verify trigger, affected resource, attempted action and outcome are recorded.","gotcha":"Broad remediation permissions can turn the incident-response bot into the incident.","security":"Use least-privilege roles and human approval for high-impact actions.","lesson":"Automation should reduce response time without removing control or auditability.","evidence":"Manually verified Day 97 LinkedIn publication and artifact."},
98:{"title":"AWS Organizations & Control Tower: Multi-Account Security Governance","phase":"Cloud Security & DevSecOps","status":"published","summary":"AWS Organizations and Control Tower provide structure and governance controls for multi-account AWS environments.","architecture":"AWS Organization → OUs → Accounts → Governance Controls","how":["Separate security, production, development and shared-service concerns into appropriate accounts and OUs.","Use SCPs to define organization-level permission ceilings.","Use Control Tower to establish and govern a landing zone with guardrails and best practices."],"commands":"Organization → Security OU / Production OU / Development OU / Shared Services OU","verify":"Confirm intended accounts sit in the correct OUs and applicable SCPs enforce the expected boundaries.","gotcha":"An SCP does not grant permissions; IAM or resource policies must still allow the action.","security":"Account structure itself becomes part of the security architecture.","lesson":"Multi-account governance reduces blast radius and creates clearer security boundaries.","evidence":"Manually verified Day 98 LinkedIn publication and artifact."},
99:{"title":"Production AWS Security Review: Connecting the Controls","phase":"Cloud Security Capstone","status":"published","summary":"Review a production-style AWS workload as one connected security system rather than a collection of individually enabled services.","architecture":"Internet → AWS WAF → ALB → Application Tier → Database Tier","how":["Verify IAM, Security Groups, Secrets Manager and CloudTrail protect the workload at their intended boundaries.","Confirm GuardDuty and Security Hub findings reach the response workflow through EventBridge and controlled automation.","Check Organizations and SCPs enforce the intended governance boundaries."],"commands":"GuardDuty Finding → Security Hub → EventBridge → Response Workflow → Verification and Evidence","verify":"Walk the architecture end to end and verify every control is associated, scoped, observable and producing reviewable evidence.","gotcha":"A security service being enabled does not prove the workload is protected.","security":"Production security depends on boundaries, visibility, detection, controlled response and governance working together.","lesson":"Each control becomes useful when you can verify where it sits, what it protects and what happens when it detects a problem.","evidence":"Manually verified Day 99 LinkedIn publication and artifact."}
}
